import{z as o,x as B,o as E,c as A,q as i,j as s,D as e,d as n,s as l,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"信贷配给 Stiglitz–Weiss","description":"","frontmatter":{"title":"信贷配给 Stiglitz–Weiss","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/stiglitz-weiss.md","filePath":"econ/stiglitz-weiss.md","lastUpdated":1791063341000}'),p={name:"econ/stiglitz-weiss.md"};function d(m,a,c,h,D,_){const t=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=i('<h1 id="信贷配给-stiglitz–weiss" tabindex="-1">信贷配给 Stiglitz–Weiss <a class="header-anchor" href="#信贷配给-stiglitz–weiss" aria-label="Permalink to &quot;信贷配给 Stiglitz–Weiss&quot;">​</a></h1><div class="epigraph"><p>提高贷款利率会改变借款人的池子与激励；银行的期望回报可以在某一利率上见顶，于是宁可靠数量配给，也不用利率把市场出清。</p><footer>—— Stiglitz and Weiss, Credit Rationing in Markets with Imperfect Information, American Economic Review 1981</footer></div><p><a href="/econ/why-intermediaries">上一课</a>把银行钉成把初级债权改写成间接债权的转换器：期限、流动性、委托监督。本课的缺口是价格为何不能单独完成配对——逆向选择（以及道德风险）使利率升高伤害贷款质量，均衡可以是配给。Diamond–Dybvig 从下一课起把活期合同收成挤兑；本课先留在资产侧的信贷合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完整市场里，<a href="/econ/state-contingent">或有要求权</a>按状态定价，风险更高的项目付更高的 \\(r\\)。Gurley–Shaw 已经说明初级贷款难以公开交易，但还没有说明：银行为什么不把利率开到使供求相等。Stiglitz 与 Weiss（1981）的缺口是：借款人质量不可观察时，利率本身是筛选与激励。提高 \\(r\\) 赶走安全项目、留下冒险项目，或诱使已借款人选择更大风险。银行利润可以在瓦尔拉斯利率之前就达到最大，于是宁愿拒绝一部分看起来相同的借款人，也不加息。</p><p>上一课并列了期限转换与委托监督。本课只取资产侧：即使中介已经在做监督，有限责任仍让利率变成筛选器。没有配给，后课的挤兑会像是「负债侧唯一的非价格现象」；两边都有数量配给——一边是信贷，一边是提款排队。</p><p><span class="marginnote">配给不是「政府规定利率」。它是银行最优：在同一合同利率下，有人借到、条件相同的人借不到。排队是均衡，不是摩擦噪声。</span></p><p><span class="marginnote">直觉类比：像保险公司不敢把保费开得太高——价格一提，留下的全是最讳疾忌医的高风险客户。银行加息同理：最迫切想借高息钱的，往往正是最不打算按时还的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>项目有成败两种结果，有限责任使借款人只关心上侧。安全项目与冒险项目的成功概率不同，银行分不开类型。期望收益作为贷款利率的函数可以非单调：利率升，分成升，但成功概率降。最优利率在内部，信贷需求在该点仍大于供给，配给出现。道德风险版本：利率升高降低借款人剩余，努力或安全技术被放弃，同样非单调。</p>',10)),(E(),s(r,null,{default:e(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%8F%90%E9%AB%98%E8%B4%B7%E6%AC%BE%E5%88%A9%E7%8E%87%22%5D%20--%3E%20AS%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%EF%BC%9A%E6%B1%A0%E5%AD%90%E5%8F%98%E5%B7%AE%22%5D%0A%20%20R%20--%3E%20MH%5B%22%E9%81%93%E5%BE%B7%E9%A3%8E%E9%99%A9%EF%BC%9A%E6%9B%B4%E5%86%92%E9%99%A9%22%5D%0A%20%20AS%20--%3E%20PI%5B%22%E9%93%B6%E8%A1%8C%E6%9C%9F%E6%9C%9B%E5%9B%9E%E6%8A%A5%E8%A7%81%E9%A1%B6%22%5D%0A%20%20MH%20--%3E%20PI%0A%20%20PI%20--%3E%20RAT%5B%22%E6%95%B0%E9%87%8F%E9%85%8D%E7%BB%99%EF%BC%8C%E4%B8%8D%E5%87%BA%E6%B8%85%E5%88%A9%E7%8E%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>委托监督（Diamond 1984）与配给兼容：监督降低不可观察性，但不取消有限责任。中介仍然必要——正是因为初级债权的质量不能被公开利率单独显示。抵押、净值、关系可以减弱配给；突然停止与原罪使净值下降时，配给加剧，宏观收缩被放大。本课不重写那些宏观课。</p><h3 id="不是把利率管制请回来" tabindex="-1">不是把利率管制请回来 <a class="header-anchor" href="#不是把利率管制请回来" aria-label="Permalink to &quot;不是把利率管制请回来&quot;">​</a></h3><p>管制可以造成另一种配给。Stiglitz–Weiss 说的是：即使利率自由，信息也可以让市场不出清。政策含义先是：只盯「让利率升到出清」可能恶化池子；资本、抵押、监督改变的是回报曲线的形状。MM 的无关性在此破了一角：对不可观察的借款人，切片与净值会改激励，不是纯套利。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是合同与信息，不是银行「不愿意放贷」的口味。利率同时是价格和筛选器。瓦尔拉斯拍卖人只把价格当价格，于是漏掉筛选。配给均衡下，同样可观察特征的借款人有人成功有人失败，失败者不靠加价挤进去——加价会让银行更亏。这与<a href="/econ/akerlof-lemons">柠檬市场</a>同族：质量随价格变。与挤兑不同：挤兑是负债合同的双均衡；本课是资产合同的非单调回报。后课可以把两者叠在同一张银行表上，本课不提前做博弈。</p>',5)),(E(),s(r,null,{default:e(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20RUP%5B%22%E9%93%B6%E8%A1%8C%E5%8A%A0%E6%81%AF%20r%22%5D%20--%3E%20LEAVE%5B%22%E5%AE%89%E5%85%A8%E9%A1%B9%E7%9B%AE%E7%AE%97%E4%B8%8D%E8%BF%87%E8%B4%A6%EF%BC%8C%E9%80%80%E5%87%BA%22%5D%0A%20%20RUP%20--%3E%20STAY%5B%22%E5%86%92%E9%99%A9%E9%A1%B9%E7%9B%AE%E7%95%99%E4%B8%8B%EF%BC%9A%E5%8F%8D%E6%AD%A3%E6%9C%89%E9%99%90%E8%B4%A3%E4%BB%BB%22%5D%0A%20%20LEAVE%20--%3E%20MIX%5B%22%E6%B1%A0%E5%AD%90%E5%B9%B3%E5%9D%87%E6%88%90%E5%8A%9F%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A%20%20STAY%20--%3E%20MIX%0A%20%20MIX%20--%3E%20PAY%5B%22%E5%8D%95%E4%BD%8D%E8%B4%B7%E6%AC%BE%E7%9A%84%E6%9C%9F%E6%9C%9B%E5%9B%9E%E6%94%B6%E5%8F%AF%E8%83%BD%E4%B8%8D%E5%8D%87%E5%8F%8D%E9%99%8D%22%5D%0A%20%20PAY%20--%3E%20NOBID%5B%22%E5%A4%B1%E8%B4%A5%E8%80%85%E5%8A%A0%E4%BB%B7%E4%B9%9F%E6%8C%A4%E4%B8%8D%E8%BF%9B%E5%8E%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">数字实例：借 100 万、利率 10%，安全项目（成功率 95%）还能净赚约 10 万。利率提到 20% 后要还 120 万，安全项目被吃光而退出；剩下的冒险项目成功率只有 50%，银行期望回收约 \\(120\\times 0.5=60\\) 万——利息加了 10 个点，回收反而少了一大截。</span></p><p>宏观接头：政策利率上升若恶化池子，信贷收缩可以大于欧拉所暗示的跨期替代。那是摩擦，要声明；不要把 NK 的 \\(i\\) 直接当成信贷市场出清利率。原罪使净值下降时，抵押变薄，配给曲线左移——突然停止的宏观收缩有一块来自本课的资产侧，而不是只有 UIP。Gurley–Shaw 的转换仍然必要：配给发生在中介的初级贷款上，不是发生在可公开定价的国债上。</p><p><span class="marginnote">有限责任是关键。若损失可以无成本地向借款人追索，利率又回到纯价格。破产成本与追索制度改配给的范围，不取消机制。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>1981 年模型是竞争性银行、单一利率合同，不是完整的机制设计菜单。显示原理说：在可验证信息下可以做得更细；本课的信息恰恰难以写进公共状态。不要把配给写成对瓦尔拉斯价值理论的否定，它是证券不全时的补充合同。也不要把限价簿的排队当信贷配给。影子银行用批发利率做类似筛选，后课的资本与窗口对它覆盖不全。抵押与净值把配给减弱，不把逆向选择取消——安全借款人仍可能被混在池子里。</p><p>筛选与<a href="/econ/spence-signaling">信号</a>方向相反：这里是价格恶化池子，那里是行动显示类型。银行可以要抵押、要关系，等于另写合同，不是把 1981 年的单一利率请回瓦尔拉斯。挤兑从下一课换到负债侧，资产侧的配给仍然可以同时存在。</p><p><span class="marginnote">常见误区：初学者容易以为信贷配给是银行「嫌贫爱富」，或监管把利率压住了。实际上利率完全自由，银行也主动拒绝愿意付更高利息的客户——因为多收的那点利息，抵不上池子变差带来的违约损失。</span></p><p>后课默认：信贷可以在利率未出清时配给；逆向选择使加息不是中性的价格调整。下一课把负债侧的流动性转换收成 Diamond–Dybvig 的活期存款。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>利率改变借款人池子与激励，银行期望回报可以非单调。</li><li>均衡可以是数量配给，而非瓦尔拉斯出清利率。</li><li>中介的监督功能与配给并列，不互相取消。</li><li>净值下降时配给加剧；宏观 \\(i\\) 不是信贷出清价。</li><li>有限责任是筛选器成立的关键；无限追索则利率回到纯价格。</li><li>出处：Stiglitz and Weiss, <em>AER</em> 1981。</li></ul>',10))])}const u=o(p,[["render",d]]);export{f as __pageData,u as default};
